@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* Light, frosted base extracted from the liquid-dom showcase (#fafafa / near-black text). */
  --background: oklch(0.985 0 0);
  --foreground: oklch(0.205 0 0);

  /* Glass surfaces: translucent white so backdrop-blur + specular highlight read as glass. */
  --card: oklch(1 0 0 / 0.72);
  --card-foreground: oklch(0.205 0 0);

  --popover: oklch(1 0 0 / 0.82);
  --popover-foreground: oklch(0.205 0 0);

  /* iOS blue accent (#1d9bf7). */
  --primary: oklch(0.668 0.158 245);
  --primary-foreground: oklch(1 0 0);

  --secondary: oklch(0.97 0.002 247 / 0.7);
  --secondary-foreground: oklch(0.3 0.006 250);

  --muted: oklch(0.96 0.002 247);
  --muted-foreground: oklch(0.55 0.012 252);

  --accent: oklch(0.95 0.006 247 / 0.7);
  --accent-foreground: oklch(0.24 0.006 250);

  --destructive: oklch(0.62 0.21 25);
  --destructive-foreground: oklch(1 0 0);

  /* Translucent cool border + input so edges catch light like glass. */
  --border: oklch(0.86 0.004 250 / 0.7);
  --input: oklch(1 0 0 / 0.55);
  --ring: oklch(0.668 0.158 245);
  --radius: 1.25rem;

  /* Glass helpers consumed by signature surfaces. */
  --glass-highlight: oklch(1 0 0 / 0.5);
  --glass-edge: oklch(1 0 0 / 0.6);
  --glass-blur: 1.125rem;

  /* ─── Chart palette: tonal ramp of the DS primary (one hue, five shades) ─── */
  --chart-1: var(--primary);
  --chart-2: oklch(from var(--primary) calc(l - 0.09) calc(c * 0.92) h);
  --chart-3: oklch(from var(--primary) calc(l - 0.18) calc(c * 0.84) h);
  --chart-4: oklch(from var(--primary) calc(l - 0.27) calc(c * 0.76) h);
  --chart-5: oklch(from var(--primary) calc(l - 0.36) calc(c * 0.68) h);

  /* --- Motion (soft profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 180ms;
  --transition-duration-base: 240ms;
  --transition-duration-slow: 300ms;
  --ease-out: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-in: cubic-bezier(0.895, 0.03, 0.685, 0.22);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* The squircle's radius factor. Registered so it never inherits: a rounded
   child draws its own factor, and a browser without @property reads the 1 in
   each token's fallback. The base layer sets it to 1.841 beside corner-shape. */
@property --corner-factor {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
  /* Tailwind's key for the bare `rounded` utility, nothing else. The page's
     --radius stays the 1.25rem that :root declares, and the steps below read
     that one at run time. */
  --radius: calc(0.25rem * var(--corner-factor, 1));
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  /* Every step takes the squircle factor, which is 1 until the base layer
     turns the shape on. Subtract the step first and multiply last, so a card
     and the tile inside it keep an even gap. var(--radius) here is the 1.25rem
     from :root, not the `rounded` key above, which Tailwind never emits. */
  --radius-xs: calc(0.125rem * var(--corner-factor, 1));
  --radius-sm: calc((var(--radius) - 0.5rem) * var(--corner-factor, 1));
  --radius-md: calc((var(--radius) - 0.25rem) * var(--corner-factor, 1));
  --radius-lg: calc(var(--radius) * var(--corner-factor, 1));
  --radius-xl: calc((var(--radius) + 0.375rem) * var(--corner-factor, 1));
  --radius-2xl: calc(1rem * var(--corner-factor, 1));
  --radius-3xl: calc(1.5rem * var(--corner-factor, 1));
  --radius-4xl: calc(2rem * var(--corner-factor, 1));

  /* Soft, diffuse, low-opacity shadows applied to every shadow-* utility across the DS. */
  --shadow-2xs: 0 0.0625rem 0.125rem oklch(0.45 0.02 252 / 0.05);
  --shadow-xs: 0 0.0625rem 0.1875rem oklch(0.45 0.02 252 / 0.06);
  --shadow-sm: 0 0.125rem 0.625rem oklch(0.45 0.02 252 / 0.07);
  --shadow: 0 0.25rem 1rem oklch(0.45 0.02 252 / 0.08);
  --shadow-md: 0 0.625rem 2.125rem oklch(0.45 0.02 252 / 0.09);
  --shadow-lg: 0 1.125rem 3.375rem oklch(0.45 0.02 252 / 0.1);
  --shadow-xl: 0 1.625rem 4.75rem oklch(0.45 0.02 252 / 0.11);
  --shadow-2xl: 0 2.125rem 6rem oklch(0.45 0.02 252 / 0.13);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  /* Squircle corners are the liquid-dom signature: any rounded element gets
     superellipse corners. A squircle hugs the corner tighter than a circle,
     so the radius grows by 1.841 in the same rule and the corner reads as
     soft as the circle it replaces. A browser without corner-shape skips the
     block and keeps the plain circle. Pills, avatars, badges and switches
     (rounded-full) keep the circle, as does any element that opts out with
     [corner-shape:round]: a pill's radius is clamped to half its height, so
     a squircle there turns the capsule into a box. See
     docs/ui/squircle-corners.md. */
  @supports (corner-shape: squircle) {
    :where([class*="rounded"]):not([class~="rounded-full"], [class~="[corner-shape:round]"]) {
      --corner-factor: 1.841;
      corner-shape: squircle;
    }
    /* A ::before or ::after layer draws its own corner, and the factor does
       not inherit, so each layer takes the shape and the factor itself. */
    :where([class*="before:rounded"]):not([class~="before:rounded-full"], [class~="before:[corner-shape:round]"])::before,
    :where([class*="after:rounded"]):not([class~="after:rounded-full"], [class~="after:[corner-shape:round]"])::after {
      --corner-factor: 1.841;
      corner-shape: squircle;
    }
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  /* Let textareas grow with their content instead of nested scrolling:
     smoother writing, easier-to-scan forms. */
  textarea {
    /* Fallback for browsers without field-sizing (e.g. Firefox): keep the
       textarea user-resizable so it can still be grown manually. */
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: comfortable;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 56);
  --layout-inset: calc(var(--spacing, 0.25rem) * 6);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 8);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 5);
}

